from pathlib import Path
import base64, gzip
ROOT = Path('sora-overlay')
FILES = {
'app/src/main/java/com/night/sora/model/Models.kt': '',
'app/src/main/java/com/night/sora/data/CoreRepository.kt': '',
'app/src/main/java/com/night/sora/data/MediaCatalogCache.kt': '',
'app/src/main/java/com/night/sora/ui/SoraApp.kt': '',
'app/src/main/java/com/night/sora/ui/screens/MoreScreen.kt': '',
}
for rel, encoded in FILES.items():
    target = ROOT / rel
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_bytes(gzip.decompress(base64.b64decode(encoded)))
    print(f'updated {target}')
